def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_caps = data.get('vehicle_capacities', [])
    # capacity not directly used in this approach, kept for compatibility

    # Identify cross-route hubs: first non-depot node in each non-empty route
    hubs = []
    for route in current_solution:
        hub = None
        for n in route:
            if n is not None and n != 0:
                hub = n
                break
        if hub is not None:
            hubs.append(hub)

    # Compute route-wise demands and count non-empty routes
    route_demands = []
    nonempty_route_flags = []
    for route in current_solution:
        rd = 0
        has_node = False
        for n in route:
            if n is None or n == 0:
                continue
            has_node = True
            if n < len(demands):
                rd += demands[n]
        route_demands.append(rd)
        nonempty_route_flags.append(has_node)

    # Mean route demand over non-empty routes
    total_rd = 0
    count = 0
    for i, flag in enumerate(nonempty_route_flags):
        if flag:
            total_rd += route_demands[i]
            count += 1
    mean_route_demand = (total_rd / count) if count > 0 else 0.0

    scores = []
    total_nodes = 0

    for ri, route in enumerate(current_solution):
        for node in route:
            if node is None or node == 0:
                continue
            total_nodes += 1

            # Distance to nearest hub
            hub_distance = None
            for hub in hubs:
                d = distance_matrix[node][hub] if (node < len(distance_matrix) and hub < len(distance_matrix[node])) else 0.0
                if (hub_distance is None) or (d < hub_distance):
                    hub_distance = d
            if hub_distance is None:
                hub_distance = 0.0

            # Load variation: how far this route's load deviates from the mean
            rd = route_demands[ri]
            if mean_route_demand > 0:
                load_factor = 1.0 + abs(rd - mean_route_demand) / mean_route_demand
            else:
                load_factor = 1.0

            jitter = rng.random() * 0.12 - 0.06  # [-0.06, 0.06)
            score = (hub_distance * 0.65) + (load_factor * 0.75) + jitter
            scores.append((node, score))

    if total_nodes == 0:
        k = 0
    else:
        frac = 0.18 + rng.random() * 0.26  # between 0.18 and 0.44
        k = int(round(total_nodes * frac))
        if k < 1:
            k = 1
        if k > total_nodes:
            k = total_nodes

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    scores = []
    total_non_dep = 0

    # Gather non-depot nodes per route and route demands
    node_to_route = {}
    route_to_demand = {}
    all_non_dep = []
    for r_idx, route in enumerate(current_solution):
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        total_non_dep += L

        # compute route demand
        route_demand = 0.0
        for n in non_dep:
            if n < len(demands):
                route_demand += demands[n]
        route_to_demand[r_idx] = route_demand

        for n in non_dep:
            all_non_dep.append(n)
            node_to_route[n] = r_idx

    if total_non_dep == 0:
        return [], 0

    # Precompute global average distance to other non-depot nodes for each i
    avg_distance = {}
    for i in all_non_dep:
        sum_dist = 0.0
        count = 0
        for j in all_non_dep:
            if j == i:
                continue
            if i < len(distance_matrix) and j < len(distance_matrix[i]):
                d = distance_matrix[i][j]
            else:
                d = 0.0
            sum_dist += d
            count += 1
        avg_distance[i] = (sum_dist / count) if count > 0 else 0.0

    # Compute per-node scores
    for i in all_non_dep:
        # global centrality component: higher when avg distance to others is small
        centrality = 1.0 / (1.0 + avg_distance[i])

        # route/demand component
        r = node_to_route[i]
        route_demand = route_to_demand[r]
        denom = route_demand if route_demand > 0 else 1.0
        node_demand = demands[i] if i < len(demands) else 0.0
        demand_ratio = node_demand / denom

        # cross-node penalty: distance to top-3 highest-demand neighbors
        candidates = []
        for j in all_non_dep:
            if j == i:
                continue
            if i < len(distance_matrix) and j < len(distance_matrix[i]):
                d = distance_matrix[i][j]
            else:
                d = 0.0
            dem_j = demands[j] if j < len(demands) else 0.0
            candidates.append((j, d, dem_j))

        top3 = sorted(candidates, key=lambda t: t[2], reverse=True)[:3]
        penalty = 0.0
        if top3:
            sumd = 0.0
            cnt = 0
            for (j2, d2, dem2) in top3:
                sumd += d2
                cnt += 1
            if cnt > 0:
                mean_top3 = sumd / cnt
                penalty = 0.4 * mean_top3

        score = centrality * 0.6 + demand_ratio * 0.4 - penalty

        # jitter for diversification
        score += rng.random() * 0.08 * (centrality + demand_ratio + 1.0)

        if score < 0.0:
            score = 0.0

        scores.append((i, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.08 + rng.random() * 0.18  # between 0.08 and 0.26
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    scores = []
    total_nodes = 0

    total_routes = len(current_solution)

    # Precompute which routes contain at least one non-depot node for diversity computation
    nonempty_route_flags = []
    for route in current_solution:
        has_node = False
        for n in route:
            if n is not None and n != 0:
                has_node = True
                break
        nonempty_route_flags.append(has_node)

    # Compute per-route loads (sum of demands for non-depot nodes)
    route_loads = []
    for route in current_solution:
        load = 0
        for node in route:
            if node is None or node == 0:
                continue
            if node < len(demands):
                load += demands[node]
        route_loads.append(load)

    # Derive diversity metrics (based on loads across nonempty routes)
    nonempty_indices = [i for i, flag in enumerate(nonempty_route_flags) if flag]
    loads_nonempty = [route_loads[i] for i in nonempty_indices]
    if loads_nonempty:
        max_load = max(loads_nonempty)
        min_load = min(loads_nonempty)
        avg_load = sum(loads_nonempty) / len(loads_nonempty)
        denom = max_load - min_load
    else:
        max_load = min_load = avg_load = 0
        denom = 0

    # Weights tuned to be different from the original algorithm
    w_sav = 1.0
    w_int = 1.2
    w_div = 0.6

    for ri, route in enumerate(current_solution):
        m = len(route)
        if m == 0:
            continue

        for idx, node in enumerate(route):
            if node is None or node == 0:
                continue
            total_nodes += 1

            # Local removal savings (alternative formulation)
            if m == 1:
                savings = 0.0
            elif idx == 0:
                next_node = route[1]
                savings = distance_matrix[node][next_node]
            elif idx == m - 1:
                prev_node = route[idx - 1]
                savings = distance_matrix[prev_node][node]
            else:
                prev_node = route[idx - 1]
                next_node = route[idx + 1]
                savings = (distance_matrix[prev_node][node] +
                           distance_matrix[node][next_node] -
                           distance_matrix[prev_node][next_node])

            # Inter-route proximity: distance to nearest node in a different route
            min_dist_to_other = None
            for rj, other_route in enumerate(current_solution):
                if rj == ri:
                    continue
                for other_node in other_route:
                    if other_node is None or other_node == 0:
                        continue
                    d = distance_matrix[node][other_node]
                    if (min_dist_to_other is None) or (d < min_dist_to_other):
                        min_dist_to_other = d

            if min_dist_to_other is None:
                inter_route_factor = 0.0
            else:
                inter_route_factor = 1.0 / (1.0 + min_dist_to_other)

            # Diversity factor based on route load distribution
            if denom <= 0:
                diversity_factor = 0.0
            else:
                route_load = route_loads[ri]
                diversity_factor = (max_load - route_load) / denom
                if diversity_factor < 0:
                    diversity_factor = 0.0
                elif diversity_factor > 1:
                    diversity_factor = 1.0

            score = (w_sav * savings) + (w_int * inter_route_factor) + (w_div * diversity_factor)
            score += rng.random() * 0.02  # small jitter for diversification

            scores.append((node, score))

    if total_nodes == 0:
        k = 0
    else:
        max_k = max(1, total_nodes // 3)
        k = int(rng.integers(1, max_k + 1))

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    scores = []
    all_nodes = []

    # collect all non-depot nodes
    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        if non_dep:
            all_nodes.extend(non_dep)

    total_non_dep = len(all_nodes)

    if total_non_dep == 0:
        return scores, 0

    # precompute sum of inverse distances to all other non-depot nodes
    node_to_sum_inv = {}
    for node in all_nodes:
        s = 0.0
        for other in all_nodes:
            if other == node:
                continue
            d = distance_matrix[node][other]
            s += 1.0 / (d + 1e-6)
        node_to_sum_inv[node] = s

    # compute per-route statistics and scores
    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue

        # route demand
        route_demand = 0
        for n in non_dep:
            if n < len(demands):
                route_demand += demands[n]

        # route max distance within the route
        max_dist = 0.0
        for i in range(L):
            a = non_dep[i]
            for j in range(i + 1, L):
                b = non_dep[j]
                d = distance_matrix[a][b]
                if d > max_dist:
                    max_dist = d

        # route centroid: node with minimal sum of distances to others in the route
        centroid = None
        best_sum = None
        if L > 1:
            for i in range(L):
                n = non_dep[i]
                s = 0.0
                for j in range(L):
                    if i == j:
                        continue
                    s += distance_matrix[n][non_dep[j]]
                if best_sum is None or s < best_sum:
                    best_sum = s
                    centroid = n
        else:
            centroid = non_dep[0]

        # route_size_factor grows with route length
        route_size_factor = 1.0
        if L > 1:
            route_size_factor = 1.0 + 0.4 * ((L - 1) ** 0.5)

        # per-node scores
        for node in non_dep:
            sum_inv = node_to_sum_inv.get(node, 0.0)
            dist_to_centroid = distance_matrix[node][centroid] if centroid is not None else 0.0
            if max_dist > 0.0:
                coherence = 1.0 - (dist_to_centroid / (max_dist + 1e-6))
                if coherence < 0.0:
                    coherence = 0.0
                if coherence > 1.0:
                    coherence = 1.0
            else:
                coherence = 1.0

            demand = demands[node] if node < len(demands) else 0
            demand_factor = 1.0 / (1.0 + demand)

            score = sum_inv * (1.0 + 0.5 * coherence) * route_size_factor * demand_factor

            perturb = rng.random() * 0.05 * (sum_inv + 1.0)
            score += perturb

            scores.append((node, score))

    # compute k
    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.12 + rng.random() * 0.16  # between 0.12 and 0.28
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance = data['distance_matrix']
    demands = data['demands']

    scores = []
    seen = set()

    for route in current_solution:
        if not route:
            continue
        for pos, node in enumerate(route):
            if node == 0:
                continue
            if node in seen:
                continue
            seen.add(node)

            prev_node = 0 if pos == 0 else route[pos - 1]
            next_node = 0 if pos == len(route) - 1 else route[pos + 1]

            delta = distance[prev_node][node] + distance[node][next_node] - distance[prev_node][next_node]
            score = -delta - 0.01 * demands[node]
            score += rng.random() * 1e-6

            scores.append((node, float(score)))

    total_nodes = len(scores)
    if total_nodes == 0:
        k = 0
    else:
        k = max(1, int(round(0.25 * total_nodes)))
        if k > total_nodes:
            k = total_nodes

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']  # not used in this variant
    demands = data.get('demands', [])
    vehicle_caps = data.get('vehicle_capacities', [])
    cap = max(vehicle_caps) if vehicle_caps else 0

    scores = []
    total_nodes = 0

    for route in current_solution:
        if not route:
            continue
        m = len(route)

        # Compute route demand (ignore depots/None)
        route_demand = 0
        for node in route:
            if node is None or node == 0:
                continue
            if node < len(demands):
                route_demand += demands[node]

        for idx, node in enumerate(route):
            if node is None or node == 0:
                continue
            total_nodes += 1

            demand = demands[node] if node < len(demands) else 0

            # Centrality-based factor: nodes near the middle of the route are considered more disruptive
            if m > 1:
                center = (m - 1) / 2.0
                norm = abs(idx - center) / max(1.0, center)
                centrality = max(0.0, 1.0 - norm)
            else:
                centrality = 1.0

            # Slack after removing nodes from this route
            slack = cap - route_demand
            if slack < 0:
                slack = 0

            jitter = rng.random() * 0.3 - 0.15

            score = demand * (0.9 * centrality + 0.1) + (slack / (slack + 1.0)) * 0.5 + jitter
            scores.append((node, score))

    if total_nodes == 0:
        k = 0
    else:
        max_k = max(1, total_nodes // 3)
        k = int(rng.integers(1, max_k + 1))

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    scores = []
    total_non_dep = 0

    # New parameter settings (distinct from the original)
    ALPHA = 0.95          # stronger influence of route length (L-1)
    BETA = 0.08           # weight for per-node demand relative to route demand
    ATTENUATION_FACTOR = 0.3  # attenuation based on mean distance
    JITTER_SCALE = 0.25     # diversification jitter

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        total_non_dep += L

        if L == 0:
            continue

        # Compute total route demand
        route_demand = 0.0
        for n in non_dep:
            if n < len(demands):
                route_demand += demands[n]

        for idx, node in enumerate(non_dep):
            prev_node = non_dep[idx - 1] if idx > 0 else None
            next_node = non_dep[idx + 1] if idx < L - 1 else None

            # Local saving term
            saving = 0.0
            if prev_node is not None and next_node is not None:
                saving = (distance_matrix[prev_node][node]
                          + distance_matrix[node][next_node]
                          - distance_matrix[prev_node][next_node])
                if saving < 0.0:
                    saving = 0.0
            else:
                # End-node bonus proportional to the edge length
                if prev_node is not None:
                    saving = 0.2 * distance_matrix[prev_node][node]
                elif next_node is not None:
                    saving = 0.2 * distance_matrix[node][next_node]
                else:
                    saving = 0.0

            # Mean distance to other nodes in the same route
            mean_distance = 0.0
            if L > 1:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    s += distance_matrix[node][other]
                mean_distance = s / (L - 1)
            else:
                mean_distance = 0.0

            demand = demands[node] if node < len(demands) else 0.0

            score = saving * (1.0 + ALPHA * (L - 1))

            if route_demand > 0.0:
                score += BETA * (demand / route_demand)

            attenuation = 1.0 / (1.0 + mean_distance * ATTENUATION_FACTOR)
            score *= attenuation

            perturb = rng.random() * JITTER_SCALE * (saving + mean_distance + 1.0)
            score += perturb

            if score < 0.0:
                score = 0.0

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.06 + rng.random() * 0.12
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_capacities = data.get('vehicle_capacities', [])

    scores = []
    total_non_dep = 0

    for r_idx, route in enumerate(current_solution):
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue

        total_non_dep += L

        route_demand = 0
        for node in non_dep:
            if node < len(demands):
                route_demand += demands[node]
        capacity = vehicle_capacities[r_idx] if r_idx < len(vehicle_capacities) else 0
        if capacity <= 0:
            remaining_ratio = 0.0
        else:
            remaining_ratio = (capacity - route_demand) / capacity
            if remaining_ratio < 0.0:
                remaining_ratio = 0.0
            if remaining_ratio > 1.0:
                remaining_ratio = 1.0

        # Route diversity factor (slower growth)
        diversity = 1.0 + 0.05 * (L - 1)

        for node in non_dep:
            if L > 1:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    s += distance_matrix[node][other]
                mean_distance = s / (L - 1)
            else:
                mean_distance = 0.0

            node_demand = demands[node] if node < len(demands) else 0

            # Weighted by remaining capacity (moderate impact)
            load_factor = 1.0 + 0.4 * (1.0 - remaining_ratio)

            score = (mean_distance ** 0.85) * diversity * load_factor
            score /= (1.0 + 0.8 * node_demand)

            perturb = rng.random() * 0.04 * (mean_distance + 0.5)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.15 + rng.random() * 0.25  # between 0.15 and 0.40
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    scores = []
    node_scores = {}
    total_non_dep = 0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue

        total_non_dep += L

        # Precompute base influence for each node in this route
        base_influence = {}
        for node in non_dep:
            demand = demands[node] if node < len(demands) else 0
            base_influence[node] = 1.0 / (1.0 + 0.5 * demand)

        # Diffusion-like one-step influence: each node i collects contributions from others j
        for i in non_dep:
            score_i = 0.0
            for j in non_dep:
                if j == i:
                    continue
                dist = distance_matrix[i][j]
                weight = 1.0 / (1.0 + dist)
                score_i += base_influence[j] * weight
            node_scores[i] = node_scores.get(i, 0.0) + score_i

    # Build scores list
    for node, sc in node_scores.items():
        scores.append((node, sc))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.05 + rng.random() * 0.15  # 0.05 to 0.20
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    scores = []
    all_non_dep = []
    node_route_len = {}
    total_nodes = 0

    # Gather all non-depot nodes and their route lengths
    for route in current_solution:
        non_dep = [n for n in route if n is not None and n != 0]
        L = len(non_dep)
        if L == 0:
            continue
        for n in non_dep:
            total_nodes += 1
            node_route_len[n] = L
            all_non_dep.append(n)

    # Compute centrality-like score for each node
    for i in all_non_dep:
        centrality = 0.0
        for j in all_non_dep:
            if j == i:
                continue
            dist = 0.0
            if i < len(distance_matrix) and j < len(distance_matrix[i]):
                dist = distance_matrix[i][j]
            if dist <= 0.0:
                dist = 1e-6
            centrality += 1.0 / dist

        L = node_route_len.get(i, 1)
        route_factor = 1.0 + 0.3 * (L - 1)
        d = demands[i] if i < len(demands) else 0
        score = centrality * route_factor + d * 0.7

        score += rng.random() * 0.01 * (centrality + 1.0)
        scores.append((i, score))

    if total_nodes == 0:
        k = 0
    else:
        frac = 0.18 + rng.random() * 0.18  # between 0.18 and 0.36
        k = max(1, int(round(total_nodes * frac)))
        if k > total_nodes:
            k = total_nodes

    return scores, k

