            score = saving * (1.0 + ALPHA * (L - 1))

            if route_demand > 0.0:
                score += BETA * (demand / route_demand)

            attenuation = 1.0 / (1.0 + mean_distance * ATTENUATION_FACTOR)
            score *= attenuation

            perturb = rng.random() * JITTER_SCALE * (saving + mean_distance + 1.0)
            score += perturb

            if score < 0.0:
                score = 0.0

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.08 + rng.random() * 0.14
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    total_nodes = 0

    scores_map = {}

    for route in current_solution:
        if not route:
            continue
        non_dep = [n for n in route if n is not None and n != 0]
        L = len(non_dep)
        if L == 0:
            continue

        total_nodes += L
        P = 3  # number of random bipartitions

        for _ in range(P):
            clusters = {0: [], 1: []}
            for node in non_dep:
                cluster = 0 if rng.random() < 0.5 else 1
                clusters[cluster].append(node)

            for c in (0, 1):
                cluster_nodes = clusters[c]
                m = len(cluster_nodes)
                if m <= 1:
                    for node in cluster_nodes:
                        scores_map[node] = scores_map.get(node, 0.0)
                    continue

                for node in cluster_nodes:
                    s = 0.0
                    for other in cluster_nodes:
                        if other == node:
                            continue
                        s += distance_matrix[node][other]
                    mean_dist = s / (m - 1)
                    contrib = 1.0 / (mean_dist + 1.0)
                    scores_map[node] = scores_map.get(node, 0.0) + contrib

    # Optional demand-based boost
    max_demand = max(demands) if demands else 0
    if max_demand > 0 and scores_map:
        for node in list(scores_map.keys()):
            demand = demands[node] if node < len(demands) else 0
            scores_map[node] += 0.25 * (demand / max_demand)

    scores = [(node, score) for node, score in scores_map.items()]

    if total_nodes == 0:
        k = 0
    else:
        frac = 0.15 + rng.random() * 0.2  # between 0.15 and 0.35
        k = int(round(total_nodes * frac))
        if k < 1:
            k = 1
        if k > total_nodes:
            k = total_nodes

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    # Gather all non-depot nodes and route information
    non_dep_nodes = []
    node_to_route = {}
    route_lengths = []
    route_demands = []

    for r_idx, route in enumerate(current_solution):
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        route_lengths.append(L)

        # total demand for this route
        rd = 0.0
        for n in non_dep:
            if n < len(demands):
                rd += demands[n]
        route_demands.append(rd)

        for n in non_dep:
            non_dep_nodes.append(n)
            node_to_route[n] = r_idx

    total_non_dep = len(non_dep_nodes)
    if total_non_dep == 0:
        return [], 0

    # max route length to scale the influence of longer routes
    max_L = max(route_lengths) if route_lengths else 1

    # Derive a radius R from the median inter-node distance among non-depot nodes
    distances_between_nodes = []
    nd = non_dep_nodes
    n = len(nd)
    for i_idx in range(n):
        i = nd[i_idx]
        for j_idx in range(i_idx + 1, n):
            j = nd[j_idx]
            if i < len(distance_matrix) and j < len(distance_matrix[i]):
                distances_between_nodes.append(distance_matrix[i][j])
            else:
                distances_between_nodes.append(0)
    if distances_between_nodes:
        distances_between_nodes.sort()
        mid = len(distances_between_nodes) // 2
        R = distances_between_nodes[mid]
    else:
        R = 0.0

    # Compute density for each node: number of other non-depot nodes within radius R
    densities = {}
    if R > 0:
        for i in nd:
            di = 0
            for j in nd:
                if i == j:
                    continue
                if i < len(distance_matrix) and j < len(distance_matrix[i]):
                    d = distance_matrix[i][j]
                else:
                    d = 0
                if d <= R:
                    di += 1
            densities[i] = di
    else:
        for i in nd:
            densities[i] = 0

    # Compute scores per node using global density, route length factor, and depot distance
    scores = []
    for i in nd:
        r_idx = node_to_route[i]
        L = route_lengths[r_idx]
        factor = 1.0 + 0.4 * ((L - 1) / max(1, max_L))
        density = densities.get(i, 0)
        depot_dist = distance_matrix[i][0] if (i < len(distance_matrix) and 0 < len(distance_matrix[i])) else 0.0

        score = density * factor + 0.6 * depot_dist

        # small random perturbation to encourage exploration
        perturb = rng.random() * 0.05 * (density + depot_dist + 1.0)
        score += perturb

        if score < 0.0:
            score = 0.0
        scores.append((i, score))

    # Determine k: fraction of non-depot nodes to remove (randomized, but anchored)
    frac = 0.08 + rng.random() * 0.12  # between 0.08 and 0.20
    k = max(1, int(round(total_non_dep * frac)))
    if k > total_non_dep:
        k = total_non_dep

    return scores, k

