            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    scores = []
    total_non_dep = 0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        total_non_dep += L

        if L == 0:
            continue

        route_demand = 0.0
        for n in non_dep:
            if n < len(demands):
                route_demand += demands[n]

        mean_dep = 0.0
        if L > 0:
            s = 0.0
            for n in non_dep:
                s += distance_matrix[0][n]
            mean_dep = s / L

        if L > 1:
            best_centroid = non_dep[0]
            best_sum = None
            for c in non_dep:
                s = 0.0
                for t in non_dep:
                    if t == c:
                        continue
                    s += distance_matrix[c][t]
                if best_sum is None or s < best_sum:
                    best_sum = s
                    best_centroid = c
            centroid = best_centroid
        else:
            centroid = non_dep[0]

        for idx, node in enumerate(non_dep):
            prev_node = non_dep[idx - 1] if idx > 0 else 0
            next_node = non_dep[idx + 1] if idx < L - 1 else 0

            saving = distance_matrix[prev_node][node] + distance_matrix[node][next_node] - distance_matrix[prev_node][next_node]
            if saving < 0.0:
                saving = 0.0

            targets = [0] + non_dep[:idx] + non_dep[idx+1:]
            if len(targets) > 0:
                mean_distance = 0.0
                for t in targets:
                    mean_distance += distance_matrix[node][t]
                mean_distance /= len(targets)
            else:
                mean_distance = 0.0

            node_demand = demands[node] if node < len(demands) else 0.0

            load_bonus = 0.0
            if route_demand > 0.0:
                load_bonus = 0.5 * (node_demand / route_demand)

            score = saving + load_bonus

            attenuation = 1.0 / (1.0 + mean_distance)
            score *= attenuation

            if mean_distance > 0.0:
                d_to_centroid = distance_matrix[node][centroid]
                centroid_penalty = 1.0 + (d_to_centroid / (mean_distance + 1e-9))
                score /= centroid_penalty

            perturb = rng.random() * 0.12 * (saving + mean_distance + 1.0)
            score += perturb

            if score < 0.0:
                score = 0.0

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.04 + rng.random() * 0.15
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_caps = data.get('vehicle_capacities', [])
    cap = max(vehicle_caps) if vehicle_caps else 0

    scores = []
    # collect all non-depot nodes and map each to its route
    all_nodes = []
    node_routes = {}
    for r_idx, route in enumerate(current_solution):
        for node in route:
            if node is None:
                continue
            if node != 0:
                all_nodes.append(node)
                node_routes[node] = r_idx

    total_non_dep = len(all_nodes)
    if total_non_dep == 0:
        return scores, 0

    # max distance to depot for normalization
    max_dist_to_depot = 0
    for node in all_nodes:
        d = distance_matrix[node][0]
        if d > max_dist_to_depot:
            max_dist_to_depot = d

    # max distance across all pairs for center normalization
    max_dist_all = 0
    n_nodes_all = len(distance_matrix)
    for i in range(n_nodes_all):
        row = distance_matrix[i]
        for j in range(n_nodes_all):
            if row[j] > max_dist_all:
                max_dist_all = row[j]
    if max_dist_all == 0:
        max_dist_all = 1

    # per-route demand and node lists
    route_demands = {}
    route_nodes_map = {}
    for r_idx, route in enumerate(current_solution):
        non_dep_in_route = [n for n in route if n != 0 and n is not None]
        L = len(non_dep_in_route)
        dsum = 0
        for n in non_dep_in_route:
            if n < len(demands):
                dsum += demands[n]
        route_demands[r_idx] = dsum
        route_nodes_map[r_idx] = non_dep_in_route

    max_demand = max(demands) if demands else 0
    if max_demand <= 0:
        max_demand = 1

    # choose a global center node as the node with minimal sum of distances to all other non-depot nodes
    center_node = None
    best_sum = None
    for cand in all_nodes:
        s = 0
        for other in all_nodes:
            if other == cand:
                continue
            s += distance_matrix[cand][other]
        if best_sum is None or s < best_sum:
            best_sum = s
            center_node = cand

    for node in all_nodes:
        r = node_routes[node]
        # depot-distance normalization
        dep_norm = distance_matrix[node][0] / max_dist_to_depot if max_dist_to_depot > 0 else 0.0

        # route slack normalization
        route_demand = route_demands.get(r, 0)
        slack_norm = 0.0
        if cap > 0:
            val = (cap - route_demand) / cap
            if val < 0:
                val = 0.0
            slack_norm = val

        # demand normalization
        demand = demands[node] if node < len(demands) else 0
        demand_norm = demand / max_demand if max_demand > 0 else 0.0

        # center diversity term
        center_dist_norm = distance_matrix[node][center_node] / max_dist_all if center_node is not None else 0.0

        # small random perturbation for diversification
        jitter = rng.random() * 0.08

        # weighted combination (totals to about 1, plus jitter)
        score = (0.35 * dep_norm) + (0.25 * slack_norm) + (0.25 * demand_norm) + (0.15 * center_dist_norm) + jitter

        scores.append((node, score))

    # determine k
    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.15 + rng.random() * 0.10  # between 0.15 and 0.25
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    scores = []
    total_nodes = 0

    max_demand = max(demands) if demands else 0

    for route in current_solution:
        if not route:
            continue
        m = len(route)
        if m == 0:
            continue
        for idx, node in enumerate(route):
            if node is None or node == 0:
                continue
            total_nodes += 1

            demand = demands[node] if node < len(demands) else 0

            # Local savings with standard neighbor-based calculation
            if m == 1:
                savings = 0.0
            elif idx == 0:
                next_node = route[1]
                savings = distance_matrix[node][next_node]
            elif idx == m - 1:
                prev_node = route[idx - 1]
                savings = distance_matrix[prev_node][node]
            else:
                prev_node = route[idx - 1]
                next_node = route[idx + 1]
                savings = (distance_matrix[prev_node][node] +
                           distance_matrix[node][next_node] -
                           distance_matrix[prev_node][next_node])

            # New parameter settings: stronger decay for longer routes
            length_factor = 1.0
            for _ in range(m - 1):
                length_factor *= 0.8

            # Demand amplification
            if max_demand > 0:
                ratio = demand / max_demand
                if ratio > 0.75:
                    demand_factor = 1.6
                elif ratio > 0.5:
                    demand_factor = 1.25
                else:
                    demand_factor = 1.0 + 0.4 * ratio
            else:
                demand_factor = 1.0

            # Interior nodes have higher centrality weight
            if idx > 0 and idx < m - 1:
                centrality = 1.4
            else:
                centrality = 0.9

            score = savings * length_factor * demand_factor * centrality

            # Small random perturbation to diversify choices
            perturb = rng.normal(0.0, 0.08)
            score *= (1.0 + perturb)

            if score < 0:
                score = 0.0

            scores.append((node, score))

    if total_nodes == 0:
        k = 0
    else:
        max_k = max(1, total_nodes // 4)
        k = int(rng.integers(1, max_k + 1))

    return scores, k

