                mean_distance = s / (L - 1)
            else:
                mean_distance = 0.0

            node_demand = demands[node] if node < len(demands) else 0

            load_factor = 1.0 + 0.5 * (1.0 - remaining_ratio)
            denom = 1.0 + 0.4 * node_demand
            score = (mean_distance ** 1.4) * diversity * load_factor / denom

            perturb = rng.random() * 0.04 * (mean_distance + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.12 + rng.random() * 0.16  # between 0.12 and 0.28
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    # Build mapping from node to its route index
    node_route = {}
    for ri, route in enumerate(current_solution):
        for node in route:
            if node is None or node == 0:
                continue
            node_route[node] = ri

    scores = []
    total_nodes = 0

    for ri, route in enumerate(current_solution):
        # Collect non-depot nodes in this route
        route_nodes = []
        for n in route:
            if n is None or n == 0:
                continue
            route_nodes.append(n)
        m = len(route_nodes)
        if m == 0:
            continue

        for idx, node in enumerate(route_nodes):
            total_nodes += 1

            # Local detour savings
            if m == 1:
                savings = 0.0
            elif idx == 0:
                next_node = route_nodes[1]
                savings = distance_matrix[node][next_node]
            elif idx == m - 1:
                prev_node = route_nodes[idx - 1]
                savings = distance_matrix[prev_node][node]
            else:
                prev_node = route_nodes[idx - 1]
                next_node = route_nodes[idx + 1]
                savings = (distance_matrix[prev_node][node] +
                           distance_matrix[node][next_node] -
                           distance_matrix[prev_node][next_node])

            # Cross-route proximity: distance to nearest node in a different route
            cross_min = None
            for other_node, other_ri in node_route.items():
                if other_ri == ri:
                    continue
                d = distance_matrix[node][other_node]
                if cross_min is None or d < cross_min:
                    cross_min = d
            cross_factor = 0.0 if cross_min is None else 1.0 / (1.0 + cross_min)

            # Intra-route cohesion (mean distance to other nodes in the same route)
            intra_mean = 0.0
            if m > 1:
                s = 0.0
                for other in route_nodes:
                    if other == node:
                        continue
                    s += distance_matrix[node][other]
                intra_mean = s / (m - 1)

            # Demand term
            demand = demands[node] if node < len(demands) else 0

            # Score combines local savings, cross proximity, and demand with a cohesion penalty
            score = savings * 0.5
            score += cross_factor * 0.25
            score += (demand / (1.0 + intra_mean)) * 0.25
            jitter = (rng.random() * 0.2) - 0.1  # [-0.1, 0.1)
            score += jitter
            # Penalize high cohesion (large intra_mean) to favor removal of less-integrated nodes
            score -= 0.15 * intra_mean

            scores.append((node, score))

    if total_nodes == 0:
        k = 0
    else:
        frac = 0.08 + rng.random() * 0.12  # between 0.08 and 0.20
        k = int(round(total_nodes * frac))
        if k < 1:
            k = 1
        if k > total_nodes:
            k = total_nodes

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    scores = []
    total_non_dep = 0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        total_non_dep += L

        if L == 0:
            continue

        route_demand = 0.0
        for n in non_dep:
            if n < len(demands):
                route_demand += demands[n]

        for idx, node in enumerate(non_dep):
            prev_node = non_dep[idx - 1] if idx > 0 else 0
            next_node = non_dep[idx + 1] if idx < L - 1 else 0

            saving = distance_matrix[prev_node][node] + distance_matrix[node][next_node] - distance_matrix[prev_node][next_node]
            if saving < 0.0:
                saving = 0.0

            targets = [0] + non_dep[:idx] + non_dep[idx+1:]
            if len(targets) > 0:
                mean_distance = 0.0
                for t in targets:
                    mean_distance += distance_matrix[node][t]
                mean_distance /= len(targets)
            else:
                mean_distance = 0.0

            demand = demands[node] if node < len(demands) else 0.0

            score = saving
            if route_demand > 0.0:
                score += 0.8 * (demand / route_demand)

            attenuation = 1.0 / (1.0 + mean_distance)
            score *= attenuation

            perturb = rng.random() * 0.15 * (saving + mean_distance + 1.0)
            score += perturb

            if score < 0.0:
                score = 0.0

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.04 + rng.random() * 0.15  # between 0.04 and 0.19
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    scores = []
    total_non_dep = 0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        total_non_dep += L

        if L == 0:
            continue

        # Compute total route demand
        route_demand = 0.0
        for n in non_dep:
            if n < len(demands):
                route_demand += demands[n]

        # Pick a random anchor node within the route
        anchor = None
        if L > 0:
            anchor = non_dep[rng.integers(0, L)]

        for idx, node in enumerate(non_dep):
            # Distance to anchor (0 if anchor is not defined or indices invalid)
            dist_to_anchor = 0.0
            if anchor is not None:
                if node < len(distance_matrix) and anchor < len(distance_matrix[node]):
                    dist_to_anchor = distance_matrix[node][anchor]
                else:
                    dist_to_anchor = 0.0

            # Mean distance to other nodes in the same route
            mean_distance = 0.0
            if L > 1:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    if node < len(distance_matrix) and other < len(distance_matrix[node]):
                        s += distance_matrix[node][other]
                mean_distance = s / (L - 1)
            else:
                mean_distance = 0.0

            # Route length factor
            route_len_factor = 1.0 + 0.25 * (L - 1)

            # Score computation
            denom = 1.0 + route_demand
            score = (dist_to_anchor * route_len_factor) / denom if denom > 0.0 else 0.0

            # Attenuation based on mean distance
            attenuation = 1.0 / (1.0 + mean_distance * 0.6)
            score *= attenuation

            # Small jitter for diversification
            jitter = rng.random() * 0.25 * (dist_to_anchor + mean_distance + 1.0)
            score += jitter

            if score < 0.0:
                score = 0.0

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.05 + rng.random() * 0.18  # 5% to 23%
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    node_to_route = {}
    route_lengths = {}
    all_nodes = []

    for r_idx, route in enumerate(current_solution):
        if not route:
            continue
        non_dep_indices = [i for i, n in enumerate(route) if n is not None and n != 0]
        L = len(non_dep_indices)
        route_lengths[r_idx] = L

        for pos_in_route, idx_in_route in enumerate(non_dep_indices):
            node = route[idx_in_route]
            node_to_route[node] = (r_idx, pos_in_route)
            all_nodes.append(node)

    N = len(all_nodes)
    scores = []

    if N == 0:
        return scores, 0

    for node in all_nodes:
        s = 0.0
        for other in all_nodes:
            if other == node:
                continue
            s += distance_matrix[node][other]
        mean_all = s / (N - 1) if N > 1 else 0.0

        r_idx, pos_in_route = node_to_route[node]
        L = route_lengths.get(r_idx, 0)

        if L <= 1:
            pos_factor = 0.6
        elif pos_in_route == 0 or pos_in_route == L - 1:
            pos_factor = 0.8
        else:
            pos_factor = 1.5

        d = demands[node] if node < len(demands) else 0
        score = mean_all * pos_factor / (1.0 + 0.5 * d)

        jitter = (rng.random() - 0.5) * 0.2 * (1.0 + mean_all)
        score += jitter

        scores.append((node, score))

    frac = 0.07 + rng.random() * 0.14  # between 0.07 and 0.21
    k = max(1, int(round(N * frac)))
    if k > N:
        k = N

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    capacities = data.get('vehicle_capacities', [])
    max_capacity = max(capacities) if capacities else 1

    scores = []
    total_non_dep = 0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue

        total_non_dep += L

        # Precompute depot distances for diversity metric
        depot_dists = []
        for node in non_dep:
            if node < len(distance_matrix):
                depot_dists.append(distance_matrix[node][0])
            else:
                depot_dists.append(0.0)
        if depot_dists:
            min_dep = min(depot_dists)
            max_dep = max(depot_dists)
            if max_dep > 0:
                diversity = 1.0 + 0.5 * (max_dep - min_dep) / max_dep
            else:
                diversity = 1.0
        else:
            diversity = 1.0

        # Route demand (sum of demands for non-depot nodes in this route)
        route_demand = 0
        for n in non_dep:
            if n < len(demands):
                route_demand += demands[n]

        for node in non_dep:
            if L > 1:
                sum_to_others = 0.0
                max_to_others = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    d = distance_matrix[node][other]
                    sum_to_others += d
                    if d > max_to_others:
                        max_to_others = d
                mean_distance = sum_to_others / (L - 1)
            else:
                mean_distance = 0.0
                max_to_others = 0.0

            depot_distance = distance_matrix[node][0]

            node_demand = demands[node] if node < len(demands) else 0

            # New scoring formula: blend intra-route distances, depot distance, and route load with diversity
            base = (0.5 * mean_distance + 0.65 * max_to_others + 0.25 * depot_distance)
            score = base * (1.0 + (route_demand / max_capacity) * 0.6 + (diversity - 1.0) * 0.8)

            score /= (1.0 + node_demand)

            perturb = rng.random() * 0.05 * (mean_distance + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.08 + rng.random() * 0.16  # between 0.08 and 0.24
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_caps = data.get('vehicle_capacities', [])
    cap = max(vehicle_caps) if vehicle_caps else 0

    scores = []
    total_nodes = 0

    for route in current_solution:
        if not route:
            continue

        # consider only actual nodes (ignore depot 0)
        route_nodes = [n for n in route if n is not None and n != 0]
        L = len(route_nodes)
        if L == 0:
            continue

        # total demand on this route
        route_demand = 0
        for node in route_nodes:
            if node < len(demands):
                route_demand += demands[node]

        for idx, node in enumerate(route_nodes):
            total_nodes += 1

            # average distance from this node to others in the same route
            sum_dist = 0.0
            for other in route_nodes:
                if other == node:
                    continue
                sum_dist += distance_matrix[node][other]
            avg_dist = sum_dist / (L - 1) if L > 1 else 0.0
            connectivity = 1.0 / (1.0 + avg_dist)

            demand = demands[node] if node < len(demands) else 0
            demand_factor = 1.0 / (1.0 + demand)

            slack = cap - route_demand
            if slack < 0:
                slack = 0
            slack_ratio = slack / cap if cap > 0 else 0.0

            if cap > 0:
                logistic = 1.0 / (1.0 + (2.718281828 ** (-6.0 * (slack_ratio - 0.5))))
            else:
                logistic = 0.5

            jitter = (rng.random() - 0.5) * 0.12  # [-0.06, 0.06)

            score = connectivity * 0.5 + demand_factor * 0.25 + logistic * 0.2 + jitter
            scores.append((node, score))

    if total_nodes == 0:
        k = 0
    else:
        frac = 0.07 + rng.random() * 0.15  # between 0.07 and 0.22
        k = int(round(total_nodes * frac))
        if k < 1:
            k = 1
        if k > total_nodes:
            k = total_nodes

    return scores, k

