    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        if not non_dep:
            continue
        non_dep_total += len(non_dep)

        for i in non_dep:
            sum_dist = 0.0
            for j in non_dep:
                if j == i:
                    continue
                d = distance_matrix[i][j] if (i < len(distance_matrix) and j < len(distance_matrix[i])) else 0
                sum_dist += d
            if len(non_dep) > 1:
                avg_dist = sum_dist / (len(non_dep) - 1)
            else:
                avg_dist = 0.0

            demand = demands[i] if i < len(demands) else 0
            route_length_factor = 1.0 + 0.35 * (len(route) - 1)
            denom = 1.0 + (demand ** 0.4 if demand >= 0 else 0.0)
            score = (avg_dist ** 0.75) * route_length_factor / denom
            score += rng.random() * 0.12 * (avg_dist + 1.0)
            scores.append((i, score))

    if non_dep_total == 0:
        k = 0
    else:
        frac = 0.06 + rng.random() * 0.26
        k = max(1, int(round(non_dep_total * frac)))
        if k > non_dep_total:
            k = non_dep_total

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance = data['distance_matrix']
    demands = data['demands']

    scores = []
    total_nodes = 0
    seen = set()

    for route in current_solution:
        if not isinstance(route, (list, tuple)):
            continue
        for idx in range(len(route)):
            node = route[idx]
            if node == 0:
                continue
            if node in seen:
                continue
            seen.add(node)
            total_nodes += 1

            prev_node = route[idx - 1] if idx > 0 else 0
            next_node = route[idx + 1] if idx < len(route) - 1 else 0

            try:
                saving = distance[prev_node][node] + distance[node][next_node] - distance[prev_node][next_node]
            except Exception:
                saving = 0

            demand_i = demands[node] if node < len(demands) else 0
            score = saving - 0.01 * demand_i
            score += rng.random() * 0.1

            scores.append((node, score))

    if total_nodes == 0:
        k = 0
    else:
        k = int(round(total_nodes * 0.25))
        if k < 1:
            k = 1
        if k > len(scores):
            k = len(scores)

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    # Collect all non-depot nodes and route assignments
    all_nodes = []
    route_of_node = {}
    route_lengths = []

    for r_idx, route in enumerate(current_solution):
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        route_lengths.append(L)
        for node in non_dep:
            all_nodes.append(node)
            route_of_node[node] = r_idx

    N = len(all_nodes)
    if N == 0:
        return [], 0

    # Precompute total distance from each node to all other non-depot nodes
    total_to_others = {}
    for node in all_nodes:
        s = 0.0
        for other in all_nodes:
            if other == node:
                continue
            s += distance_matrix[node][other]
        total_to_others[node] = s

    # Precompute intra-route sums (distance to peers in the same route)
    intra_sum = {node: 0.0 for node in all_nodes}
    for r_idx, route in enumerate(current_solution):
        non_dep = [n for n in route if n != 0]
        for node in non_dep:
            for other in non_dep:
                if other == node:
                    continue
                intra_sum[node] += distance_matrix[node][other]

    # Compute per-node statistics
    global_mean = {}
    intra_mean = {}
    outside_mean = {}
    for node in all_nodes:
        r_idx = route_of_node[node]
        L = route_lengths[r_idx]
        # global mean distance to all other nodes
        global_mean[node] = total_to_others[node] / max(1, N - 1)
        # mean distance to peers in the same route
        intra_mean[node] = intra_sum[node] / max(1, (L - 1))
        # mean distance to nodes not in the same route
        outside_sum = total_to_others[node] - intra_sum[node]
        outside_mean[node] = outside_sum / max(1, N - L)

    # Compute scores
    scores = []
    for node in all_nodes:
        r_idx = route_of_node[node]
        L = route_lengths[r_idx]
        diff = global_mean[node] - intra_mean[node]  # potential cross-route isolation
        score = diff * (1.0 + 0.6 * (L - 1)) + outside_mean[node] * 0.9
        perturb = rng.random() * 0.05 * (abs(diff) + outside_mean[node] + intra_mean[node] + 1.0)
        score += perturb
        scores.append((node, score))

    # Determine k: number of nodes to remove
    total_non_dep = N
    frac = 0.15 + rng.random() * 0.25  # between 0.15 and 0.40
    k = max(1, int(round(total_non_dep * frac)))
    if k > total_non_dep:
        k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_caps = data.get('vehicle_capacities', [])
    cap = max(vehicle_caps) if vehicle_caps else 0

    scores = []
    all_nodes = []

    # collect all non-depot nodes in the solution
    for route in current_solution:
        for n in route:
            if n != 0:
                all_nodes.append(n)

    total_non_dep = len(all_nodes)

    # precompute global centrality: sum of distances from i to all other non-depot nodes
    sum_to_others = {}
    for i in all_nodes:
        s = 0.0
        row_i = distance_matrix[i]
        for j in all_nodes:
            if i == j:
                continue
            s += row_i[j]
        sum_to_others[i] = s

    # precompute route-level info for each node
    node_route_len = {}
    node_route_demand = {}

    for route in current_solution:
        route_nodes = [n for n in route if n != 0]
        m = len(route_nodes)
        route_demand = 0
        for n in route_nodes:
            if n < len(demands):
                route_demand += demands[n]
        for n in route_nodes:
            node_route_len[n] = m
            node_route_demand[n] = route_demand

    # compute scores for each non-depot node
    for route in current_solution:
        route_nodes = [n for n in route if n != 0]
        if not route_nodes:
            continue
        for node in route_nodes:
            sum_others = sum_to_others.get(node, 0.0)
            depot_distance = distance_matrix[node][0] if len(distance_matrix) > 0 and len(distance_matrix[node]) > 0 else 0.0
            demand_node = demands[node] if node < len(demands) else 0
            route_len = node_route_len.get(node, len(route_nodes))
            route_demand = node_route_demand.get(node, 0)

            # logistic-like factor based on slack relative to capacity
            if cap > 0:
                slack_ratio = (cap - route_demand) / cap
                if slack_ratio < 0:
                    slack_ratio = 0.0
                logistic_factor = 1.0 / (1.0 + (2.718281828 ** (-12.0 * (slack_ratio - 0.5))))
            else:
                logistic_factor = 0.5

            route_len_factor = 1.0 + 0.4 * ((route_len - 1) / max(1, route_len))

            jitter = (rng.random() * 0.2) - 0.1  # [-0.1, 0.1)

            score = (sum_others * 0.5 + depot_distance * 0.25 + demand_node * 0.2) * logistic_factor * route_len_factor + jitter
            scores.append((node, score))

    # determine how many nodes to remove
    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.12 + rng.random() * 0.22  # between 0.12 and 0.34
        k = int(round(total_non_dep * frac))
        if k < 1:
            k = 1
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    scores = []
    total_non_dep = 0

    # New parameter settings (distinct from the original)
    ALPHA = 0.60          # reduced influence of route length (L-1)
    BETA = 0.20           # higher weight for per-node demand relative to route demand
    ATTENUATION_FACTOR = 0.4  # stronger attenuation based on mean distance
    JITTER_SCALE = 0.35     # diversification jitter

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        total_non_dep += L

        if L == 0:
            continue

        # Compute total route demand
        route_demand = 0.0
        for n in non_dep:
            if n < len(demands):
                route_demand += demands[n]

        for idx, node in enumerate(non_dep):
            prev_node = non_dep[idx - 1] if idx > 0 else None
            next_node = non_dep[idx + 1] if idx < L - 1 else None

            # Local saving term
            saving = 0.0
            if prev_node is not None and next_node is not None:
                saving = (distance_matrix[prev_node][node]
                          + distance_matrix[node][next_node]
                          - distance_matrix[prev_node][next_node])
                if saving < 0.0:
                    saving = 0.0
            else:
                # End-node bonus proportional to the edge length
                if prev_node is not None:
                    saving = 0.12 * distance_matrix[prev_node][node]
                elif next_node is not None:
                    saving = 0.12 * distance_matrix[node][next_node]
                else:
                    saving = 0.0

            # Mean distance to other nodes in the same route
            mean_distance = 0.0
            if L > 1:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    s += distance_matrix[node][other]
                mean_distance = s / (L - 1)
            else:
                mean_distance = 0.0

            demand = demands[node] if node < len(demands) else 0.0

            score = saving * (1.0 + ALPHA * (L - 1))

            if route_demand > 0.0:
                score += BETA * (demand / route_demand)

            attenuation = 1.0 / (1.0 + mean_distance * ATTENUATION_FACTOR)
            score *= attenuation

            perturb = rng.random() * JITTER_SCALE * (saving + mean_distance + 1.0)
            score += perturb

            if score < 0.0:
                score = 0.0

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
