            score = saving * (1.0 + ALPHA2 * (L - 1))

            if route_demand > 0.0:
                score += BETA2 * (demand / route_demand)

            attenuation = 1.0 / (1.0 + (mean_distance ** 2) * ATTENUATION_COEFF2)
            score *= attenuation

            perturb = rng.random() * JITTER_SCALE2 * (saving + mean_distance + 1.0)
            score += perturb

            if score < 0.0:
                score = 0.0

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
