def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_capacities = data.get('vehicle_capacities', [])
    max_cap = max(vehicle_capacities) if vehicle_capacities else 1

    scores = []
    total_non_dep = 0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        total_non_dep += L

        if L == 0:
            continue

        # route total demand
        route_demand = 0.0
        for n in non_dep:
            if n < len(demands):
                route_demand += demands[n]

        # pre-compute route length (sum of consecutive intra-route distances)
        route_len = 0.0
        if L > 1:
            for i in range(L - 1):
                a = non_dep[i]
                b = non_dep[i + 1]
                if a < len(distance_matrix) and b < len(distance_matrix[a]):
                    route_len += distance_matrix[a][b]

        for idx, node in enumerate(non_dep):
            prev_node = non_dep[idx - 1] if idx > 0 else None
            next_node = non_dep[idx + 1] if idx < L - 1 else None

            # marginal contribution when removing this node (nonlinear form)
            saving = 0.0
            if prev_node is not None and next_node is not None:
                saving = (distance_matrix[prev_node][node]
                          + distance_matrix[node][next_node]
                          - distance_matrix[prev_node][next_node])
                if saving < 0.0:
                    saving = 0.0
            elif prev_node is not None:
                saving = distance_matrix[prev_node][node]
            elif next_node is not None:
                saving = distance_matrix[node][next_node]

            if L > 1:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    s += distance_matrix[node][other]
                mean_distance_to_others = s / (L - 1)
            else:
                mean_distance_to_others = 0.0

            distance_to_depot = distance_matrix[node][0] if node < len(distance_matrix) and 0 < len(distance_matrix[node]) else 0.0

            # nonlinear amplification based on route length and local exposure
            route_len_factor = 1.0 + ((L - 1) ** 2) * 0.25
            score = 0.0
            if saving > 0.0:
                score = saving * route_len_factor
            else:
                score = 0.0

            d = demands[node] if node < len(demands) else 0.0
            if route_demand > 0.0:
                score *= (1.0 + 0.8 * (d / route_demand))

            # depot-distance bias (prefer removing far-from-depot nodes)
            depot_bias = 1.0 + 0.4 * (distance_to_depot / (distance_to_depot + 50.0))
            score *= depot_bias

            # penalize large mean distances to other nodes (keep cohesion)
            if mean_distance_to_others > 0.0:
                score /= (1.0 + 0.6 * mean_distance_to_others)

            # small random perturbation for diversification
            perturb = rng.random() * 0.04 * (saving + mean_distance_to_others + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.08 + rng.random() * 0.18  # between 0.08 and 0.26
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data['demands']

    # Step 1: compute a center for each route (node with minimal sum of distances to other nodes in the same route)
    centers = {}
    candidate_nodes = []  # list of (node, route_index)
    for r_idx, route in enumerate(current_solution):
        nodes = [n for n in route if n != 0]
        if not nodes:
            continue
        best_center = None
        best_sum = None
        for c in nodes:
            s = 0
            row_c = distance_matrix[c]
            for o in nodes:
                if o == c:
                    continue
                s += row_c[o]
            if best_sum is None or s < best_sum:
                best_sum = s
                best_center = c
        centers[r_idx] = best_center
        for n in nodes:
            candidate_nodes.append((n, r_idx))

    total_candidates = len(candidate_nodes)
    if total_candidates == 0:
        return [], 0

    # Determine max demand for normalization
    max_demand = 1
    if isinstance(demands, dict):
        max_demand = max(demands.values()) if demands else 1
    else:
        max_demand = max(demands) if isinstance(demands, (list, tuple)) and demands else 1
    if max_demand <= 0:
        max_demand = 1

    # Step 2: compute score for each candidate node
    scores = []
    for node, r in candidate_nodes:
        own_center = centers.get(r, None)
        dist_to_own_center = distance_matrix[node][own_center] if own_center is not None else 0

        # distance to centers of other routes
        min_other_center_dist = None
        for other_r, other_center in centers.items():
            if other_r == r:
                continue
            d = distance_matrix[node][other_center]
            if min_other_center_dist is None or d < min_other_center_dist:
                min_other_center_dist = d
        if min_other_center_dist is None:
            min_other_center_dist = dist_to_own_center  # only one route exists

        # demand normalization
        demand_node = demands[node] if isinstance(demands, (list, tuple)) and node < len(demands) else 0
        norm = demand_node / max_demand

        score = (min_other_center_dist - dist_to_own_center) - 0.5 * norm
        score += rng.random() * 0.01  # small random jitter for diversification

        scores.append((node, score))

    # Step 3: determine k (fraction of candidates to remove)
    k_fraction = 0.15 + rng.random() * 0.15  # between 0.15 and 0.30
    k = max(1, int(round(total_candidates * k_fraction)))
    if k > total_candidates:
        k = total_candidates

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_capacities = data.get('vehicle_capacities', [])

    scores = []
    total_non_dep = 0

    for r_idx, route in enumerate(current_solution):
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue

        # compute route demand
        route_demand = 0
        for node in non_dep:
            if node < len(demands):
                route_demand += demands[node]

        capacity = vehicle_capacities[r_idx] if r_idx < len(vehicle_capacities) else 0
        if capacity <= 0:
            remaining_ratio = 0.0
        else:
            remaining_ratio = (capacity - route_demand) / capacity
            if remaining_ratio < 0.0:
                remaining_ratio = 0.0
            if remaining_ratio > 1.0:
                remaining_ratio = 1.0

        total_non_dep += L

        # modified diversity factor
        diversity = 1.0 + 0.03 * (L ** 0.8)

        for node in non_dep:
            if L > 1:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    s += distance_matrix[node][other]
                mean_distance = s / (L - 1)
            else:
                mean_distance = 0.0

            node_demand = demands[node] if node < len(demands) else 0

            # load factor biased by remaining capacity
            load_factor = 1.0 + 0.25 * (1.0 - remaining_ratio)

            score = (mean_distance ** 1.3) * diversity * load_factor
            score /= (1.0 + 0.6 * node_demand)

            perturb = rng.random() * 0.08 * (mean_distance + 0.5)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.12 + rng.random() * 0.25  # between 0.12 and 0.37
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_caps = data.get('vehicle_capacities', [])

    # Build per-route non-depot lists and mappings
    routes_non_dep = []
    node_to_route = {}
    all_nodes = []
    for rid, route in enumerate(current_solution):
        non_dep = [n for n in route if n != 0]
        routes_non_dep.append(non_dep)
        for n in non_dep:
            node_to_route[n] = rid
            all_nodes.append(n)
    N = len(all_nodes)

    scores = []

    # Precompute mean_global: mean distance to all non-depot nodes
    mean_global = {}
    if N > 1:
        for i in all_nodes:
            s = 0.0
            for j in all_nodes:
                if j == i:
                    continue
                d = distance_matrix[i][j] if (i < len(distance_matrix) and j < len(distance_matrix[i])) else 0.0
                s += d
            mean_global[i] = s / (N - 1)
    else:
        for i in all_nodes:
            mean_global[i] = 0.0

    # Precompute mean_intra: mean distance to other nodes within the same route
    mean_intra = {}
    for i in all_nodes:
        rid = node_to_route[i]
        non_dep = routes_non_dep[rid]
        L = len(non_dep)
        if L > 1:
            s = 0.0
            for other in non_dep:
                if other == i:
                    continue
                d = distance_matrix[i][other] if (i < len(distance_matrix) and other < len(distance_matrix[i])) else 0.0
                s += d
            mean_intra[i] = s / (L - 1)
        else:
            mean_intra[i] = 0.0

    # Compute scores for each non-depot node
    for i in all_nodes:
        mg = mean_global.get(i, 0.0)
        mi = mean_intra.get(i, 0.0)
        d = demands[i] if i < len(demands) else 0
        L = len(routes_non_dep[node_to_route[i]]) if i in node_to_route else 0

        score = (mg - mi)            # centrality difference
        score += 0.01 * max(0, L - 1) # small route-length boost
        score += 0.05 * d              # demand weighting
        # jitter to diversify
        jitter = (rng.random() - 0.5) * 0.1 * max(1.0, mg + 1.0)
        score += jitter

        scores.append((i, score))

    # Determine k
    if N == 0:
        k = 0
    else:
        frac = 0.15 + rng.random() * 0.15  # between 0.15 and 0.30
        k = max(1, int(round(N * frac)))
        if k > N:
            k = N

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_capacities = data.get('vehicle_capacities', [])
    max_capacity = max(vehicle_capacities) if vehicle_capacities else 0

    scores = []
    for route in current_solution:
        # consider non-depot nodes in their route order
        non_dep = [n for n in route if n != 0]
        m = len(non_dep)
        if m == 0:
            continue

        # route load to scale the score
        load = 0.0
        for n in non_dep:
            if n < len(demands):
                load += demands[n]
        factor = 1.0
        if max_capacity > 0:
            factor = 1.0 + (load / max_capacity)

        for idx, node in enumerate(non_dep):
            # nodes after and before in the route
            after = non_dep[idx+1:] if idx+1 < m else []
            before = non_dep[:idx] if idx > 0 else []

            forward_mean = 0.0
            if after:
                s = 0.0
                for o in after:
                    if node < len(distance_matrix) and o < len(distance_matrix[node]):
                        s += distance_matrix[node][o]
                forward_mean = s / len(after) if after else 0.0

            backward_mean = 0.0
            if before:
                t_sum = 0.0
                for o in before:
                    if node < len(distance_matrix) and o < len(distance_matrix[node]):
                        t_sum += distance_matrix[node][o]
                backward_mean = t_sum / len(before) if before else 0.0

            imbalance = abs(forward_mean - backward_mean)
            score = imbalance * factor

            jitter = rng.random() * 0.01 * (imbalance + 1.0)
            score += jitter

            scores.append((node, score))

    total_nodes = len(scores)
    if total_nodes == 0:
        k = 0
    else:
        frac = 0.10 + rng.random() * 0.15  # fraction between 0.10 and 0.25
        k = max(1, int(round(total_nodes * frac)))
        if k > total_nodes:
            k = total_nodes

    return scores, k

def score_state(state):
    score = 0
    for lane in state:
        blocking = False
        for load in lane:
            if load == 0:
                blocking = True
            elif blocking and load > 0:
                score += 1
    return score

def score_state(state):
    score = 0
    for lane in state:
        max_val = 0
        block_count = 0
        priority_sum = 0
        is_sorted = True
        lane_length = len(lane)

        for load in lane:
            if load != 0:
                if max_val > load:
                    block_count += 1
                    priority_sum += load
                    is_sorted = False
                else:
                    block_count = 0
                max_val = load

        if block_count > 1:
