def score_state(state):
    score = 0
    for lane in state:
        highest_priority = None
        for i, load in enumerate(lane):
            if load != 0:
                if highest_priority is not None and load < highest_priority:
                    score += (highest_priority - load) * (i + 1)
                highest_priority = load
    return score

def score_state(state):
    score = 0.0
    for lane in state:
        non_empty_start = next((i for i, x in enumerate(lane) if x != 0), len(lane))
        max_blocked_priority = 0
        blocked_count = 0
        for i in range(non_empty_start, len(lane)):
            current_load = lane[i]
            for j in range(i + 1, len(lane)):
                if lane[j] != 0 and current_load > lane[j]:
                    blocked_count += 1
                    max_blocked_priority = max(max_blocked_priority, lane[j])
        score += blocked_count * max_blocked_priority
    return score

def score_state(state):
    score = 0
    for lane in state:
        max_val = 0
        block_count = 0
        is_sorted = True

        for idx, load in enumerate(lane):
            if load != 0:
                if max_val > load:
                    block_count += 1
                    moves_to_unblock = sum(1 for i in range(idx + 1, len(lane)) if lane[i] < load)
                    penalty = (block_count * load * moves_to_unblock) / len(lane)
                    score += penalty
                    is_sorted = False
                else:
                    block_count = 0
                max_val = load

        if not is_sorted:
            score += sum(load for load in lane if load != 0) / len(lane)

        if lane and lane[0] == max_val:
            score -= 1

    return score

def score_state(state):
    score = 0.0
    for lane in state:
        non_empty_start = next((i for i, x in enumerate(lane) if x != 0), len(lane))
        for i in range(non_empty_start, len(lane)):
            current_load = lane[i]
            target_position = next((j for j, x in enumerate(lane[non_empty_start:]) if x == current_load), None)
            if target_position is not None:
                score += (i - non_empty_start - target_position) * current_load
    return score

def score_state(state):
    score = 0.0
    base_penalty = 1.5
    decay_factor = 0.9
    for lane in state:
        highest_priority = None
        depth_penalty = 0
        for i in range(len(lane)):
            if lane[i] != 0:
                if highest_priority is not None and lane[i] < highest_priority:
                    score += base_penalty ** depth_penalty * (decay_factor ** depth_penalty)
                highest_priority = lane[i]
                depth_penalty += 1
    return score

def score_state(state):
    score = 0.0
    for lane in state:
        non_empty_start = next((i for i, x in enumerate(lane) if x != 0), len(lane))
        ideal_order = sorted(lane[non_empty_start:], reverse=True)
        for i in range(non_empty_start, len(lane)):
            if lane[i] == 0:
                continue
            optimal_position = ideal_order.index(lane[i])
            penalty = abs(i - non_empty_start - optimal_position)
            score += (lane[i] * penalty)
    return score

def score_state(state):
    score = 0
    for lane in state:
        max_priority_seen = 0
        block_count = 0
        cumulative_penalty = 0
        lane_length = len(lane)
        for i, load in enumerate(lane):
            if load != 0:
                if max_priority_seen > load:
                    block_count += 1
                    cumulative_penalty += (max_priority_seen - load) / max_priority_seen * (1 + 0.5 * (lane_length - i))
                max_priority_seen = load
        score += cumulative_penalty + block_count * 2
    return score

def score_state(state):
    score = 0
    priority_weights = {1: 5, 2: 4, 3: 3, 4: 2, 5: 1}  # Adjusted weights for priorities

    for lane in state:
        max_val = 0
        blocked_positions = []
        blocked_priorities = set()

        for idx, load in enumerate(lane):
            if load != 0:
                if max_val > load:
                    blocked_positions.append(idx)
                    blocked_priorities.add(load)
                else:
                    blocked_positions = []
                max_val = load

        lane_length = len(lane)
        cumulative_distance = sum(
            sum(priority_weights[lane[j]] for j in range(pos + 1, lane_length) if lane[j] != 0 and lane[j] < load) 
            for pos, load in zip(blocked_positions, (lane[pos] for pos in blocked_positions))
        )

        score += (cumulative_distance / lane_length) + len(blocked_priorities) * 2

    return score

def score_state(state):
    N = len(state)
    score = 0
    misplaced_tiles = set()

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                goal_i, goal_j = divmod(value - 1, N)
                manhattan_distance = abs(i - goal_i) + abs(j - goal_j)
                score += manhattan_distance
                if i != goal_i or j != goal_j:
                    misplaced_tiles.add((i, j))

    for (i, j) in misplaced_tiles:
        min_penalty = float('inf')
        value = state[i][j]
        goal_i, goal_j = divmod(value - 1, N)

        for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            ni, nj = i + di, j + dj
            if 0 <= ni < N and 0 <= nj < N and state[ni][nj] != 0:
                n_goal_i, n_goal_j = divmod(state[ni][nj] - 1, N)
                penalty = abs(ni - goal_i) + abs(nj - goal_j)
                if penalty == 0:
                    min_penalty = 0
                    break
                else:
                    min_penalty = min(min_penalty, penalty * 0.9 ** penalty)

        score += min_penalty

    for i in range(N):
        row_tiles = [(state[i][j], j) for j in range(N) if state[i][j] != 0 and (state[i][j] - 1) // N == i]
        row_tiles.sort(key=lambda x: divmod(x[0] - 1, N)[1])
        for k in range(len(row_tiles) - 1):
            if row_tiles[k][1] > row_tiles[k + 1][1]:
                score += abs(row_tiles[k][1] - row_tiles[k + 1][1]) * 2

    for j in range(N):
        col_tiles = [(state[i][j], i) for i in range(N) if state[i][j] != 0 and (state[i][j] - 1) % N == j]
        col_tiles.sort(key=lambda x: divmod(x[0] - 1, N)[0])
        for k in range(len(col_tiles) - 1):
            if col_tiles[k][1] > col_tiles[k + 1][1]:
                score += abs(col_tiles[k][1] - col_tiles[k + 1][1]) * 2

    return score

def score_state(state):
    N = len(state)
    score = 0

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                goal_i, goal_j = divmod(value - 1, N)
                manhattan_distance = abs(i - goal_i) + abs(j - goal_j)
                score += manhattan_distance

    # Row and column inversion penalties
    for i in range(N):
        row_tiles = [(state[i][j], j) for j in range(N) if state[i][j] != 0]
        row_tiles.sort(key=lambda x: divmod(x[0] - 1, N)[1])
        inversions = sum(1 for k in range(len(row_tiles)) for l in range(k + 1, len(row_tiles)) if row_tiles[k][1] > row_tiles[l][1])
        score += inversions * 2

    for j in range(N):
        col_tiles = [(state[i][j], i) for i in range(N) if state[i][j] != 0]
        col_tiles.sort(key=lambda x: divmod(x[0] - 1, N)[0])
        inversions = sum(1 for k in range(len(col_tiles)) for l in range(k + 1, len(col_tiles)) if col_tiles[k][1] > col_tiles[l][1])
        score += inversions * 2

    # Obstruction penalty
    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                goal_i, goal_j = divmod(value - 1, N)
                obstructed_tiles = sum(1 for ni in range(i + 1, N) for nj in range(j, j + 1) if state[ni][nj] != 0 and (state[ni][nj] - 1) // N == i)
                score += obstructed_tiles * 1.5

    return score

def score_state(state):
    N = len(state)
    score = 0
    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i = (value - 1) // N
                target_j = (value - 1) % N
                score += abs(i - target_i) + abs(j - target_j)
                if i != target_i:
                    score += 0.3  # Penalty for not being in the correct row
                if j != target_j:
                    score += 0.2  # Penalty for not being in the correct column
    return score

def score_state(state):
    N = len(state)
    score = 0
    total_distance = 0
    row_positions = [set() for _ in range(N)]
    col_positions = [set() for _ in range(N)]

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                distance = abs(i - target_i) + abs(j - target_j)
                total_distance += distance
                score += distance
                row_positions[target_i].add((value, j))
                col_positions[target_j].add((value, i))

    def count_misplaced_neighbors(positions):
        sorted_positions = sorted(positions, key=lambda x: x[0])
        misplaced = 0
        for k in range(1, len(sorted_positions)):
            if sorted_positions[k][1] < sorted_positions[k - 1][1]:
                misplaced += 1
        return misplaced

    for positions in row_positions:
        score += count_misplaced_neighbors(positions)

    for positions in col_positions:
        score += count_misplaced_neighbors(positions)

    score += total_distance

    return score

def score_state(state):
    N = len(state)
    target_positions = {(i + 1): (i // N, i % N) for i in range(1, N * N)}
    row_conflicts = [set() for _ in range(N)]
    col_conflicts = [set() for _ in range(N)]

    for i in range(N):
        for j in range(N):
            tile = state[i][j]
            if tile != 0:
                target_i, target_j = target_positions[tile]
                if target_i == i and any(state[i][k] != 0 and (state[i][k] - 1) // N == i and (state[i][k] - 1) % N > j for k in range(j + 1, N)):
                    row_conflicts[i].add((j, target_j))
                if target_j == j and any(state[k][j] != 0 and (state[k][j] - 1) % N == j and (state[k][j] - 1) // N > i for k in range(i + 1, N)):
                    col_conflicts[j].add((i, target_i))

    linear_conflicts = sum(len(conflict_set) - 1 for conflict_set in row_conflicts if len(conflict_set) > 1)
    linear_conflicts += sum(len(conflict_set) - 1 for conflict_set in col_conflicts if len(conflict_set) > 1)

    return linear_conflicts

def score_state(state):
    N = len(state)
    score = 0

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                manhattan_distance = abs(i - target_i) + abs(j - target_j)
                score += manhattan_distance
                if i != target_i:
                    score += (N - abs(i - target_i)) / N
                if j != target_j:
                    score += (N - abs(j - target_j)) / N

    center_i, center_j = N // 2, N // 2
    decay_factor = 0.85

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                distance_from_center = abs(i - center_i) + abs(j - center_j)
                score += (distance_from_center / (N * 2)) * (1 - decay_factor ** distance_from_center)

    return score

def score_state(state):
    N = len(state)
    score = 0
    misplaced_tiles = set()

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                goal_i, goal_j = divmod(value - 1, N)
                manhattan_distance = abs(i - goal_i) + abs(j - goal_j)
                score += manhattan_distance
                if i != goal_i or j != goal_j:
                    misplaced_tiles.add((i, j))

    # Linear conflicts calculation
    for row in range(N):
        max_value_in_row = 0
        for col in range(N):
            value = state[row][col]
            if value != 0 and (value - 1) // N == row:
                if value > max_value_in_row:
                    max_value_in_row = value
                else:
                    score += 2

    for col in range(N):
        max_value_in_col = 0
        for row in range(N):
            value = state[row][col]
            if value != 0 and (value - 1) % N == col:
                if value > max_value_in_col:
                    max_value_in_col = value
                else:
                    score += 2

    for (i, j) in misplaced_tiles:
        value = state[i][j]
        goal_i, goal_j = divmod(value - 1, N)
        min_penalty = float('inf')

        # Check neighbors for penalty adjustment with adaptive weight
        for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            ni, nj = i + di, j + dj
            if 0 <= ni < N and 0 <= nj < N and state[ni][nj] != 0:
                n_value = state[ni][nj]
                n_goal_i, n_goal_j = divmod(n_value - 1, N)
                penalty = abs(ni - goal_i) + abs(nj - goal_j)
                if penalty == 0:
                    min_penalty = 0
                    break
                else:
                    # Adaptive weight factor based on distance to midpoint of goal path
                    midpoint_distance = abs((goal_i + i) // 2 - ni) + abs((goal_j + j) // 2 - nj)
                    weight_factor = (midpoint_distance / (N // 2)) + 1 if midpoint_distance > 0 else 1
                    min_penalty = min(min_penalty, penalty * weight_factor)

        score += min_penalty

    return score

def score_state(state):
    N = len(state)
    score = 0

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                manhattan_distance = abs(i - target_i) + abs(j - target_j)
                score += manhattan_distance

                # Calculate the number of misplaced tiles around the current tile
                neighbors_misplaced = 0
                for x in range(max(0, i-1), min(N, i+2)):
                    for y in range(max(0, j-1), min(N, j+2)):
                        if (x != i or y != j) and state[x][y] != 0:
                            neighbor_value = state[x][y]
                            neighbor_target_i, neighbor_target_j = divmod(neighbor_value - 1, N)
                            if (neighbor_target_i != x or neighbor_target_j != y):
                                neighbors_misplaced += 1

                # Apply dynamic weighting factor based on the number of misplaced neighbors
                weight_factor = 1 + 0.5 * neighbors_misplaced
                score += weight_factor * manhattan_distance

    return score

def score_state(state):
    N = len(state)
    score = 0
    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                manhattan_distance = abs(i - target_i) + abs(j - target_j)
