                score += abs(i - target_i) + abs(j - target_j)
    for i in range(N):
        row = [state[i][j] for j in range(N)]
        for j in range(N-1):
            if row[j] != 0 and row[j+1] != 0:
                target_row_j = (row[j] - 1) // N
                target_row_jp1 = (row[j+1] - 1) // N
                if target_row_j == i and target_row_jp1 == i and row[j] > row[j+1]:
                    score += 1.5
    for j in range(N):
        col = [state[i][j] for i in range(N)]
        for i in range(N-1):
            if col[i] != 0 and col[i+1] != 0:
                target_col_i = (col[i] - 1) % N
                target_col_ip1 = (col[i+1] - 1) % N
                if target_col_i == j and target_col_ip1 == j and col[i] > col[i+1]:
                    score += 1.5
    return score

def score_state(state):
    N = len(state)
    score = 0
    misplaced_tiles = set()

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                goal_i, goal_j = divmod(value - 1, N)
                manhattan_distance = abs(i - goal_i) + abs(j - goal_j)
                score += manhattan_distance
                if i != goal_i or j != goal_j:
                    misplaced_tiles.add((i, j))

    for (i, j) in misplaced_tiles:
        value = state[i][j]
        goal_i, goal_j = divmod(value - 1, N)
        min_penalty = float('inf')

        # Check neighbors for penalty adjustment with adaptive weight
        for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            ni, nj = i + di, j + dj
            if 0 <= ni < N and 0 <= nj < N and state[ni][nj] != 0:
                n_value = state[ni][nj]
                n_goal_i, n_goal_j = divmod(n_value - 1, N)
                penalty = abs(ni - goal_i) + abs(nj - goal_j)
                if penalty == 0:
                    min_penalty = 0
                    break
                else:
                    # Adaptive weight factor based on distance to midpoint of goal path
                    midpoint_distance = abs((goal_i + i) // 2 - ni) + abs((goal_j + j) // 2 - nj)
                    weight_factor = (midpoint_distance / (N // 2)) + 1 if midpoint_distance > 0 else 1
                    min_penalty = min(min_penalty, penalty * weight_factor)

        score += min_penalty

    for i in range(N):
        row_tiles = [(state[i][j], j) for j in range(N) if state[i][j] != 0 and (state[i][j] - 1) // N == i]
        row_tiles.sort(key=lambda x: divmod(x[0] - 1, N)[1])
        for k in range(1, len(row_tiles)):
            if row_tiles[k][1] < row_tiles[k - 1][1]:
                score += (N - row_tiles[k][1])

    for j in range(N):
        col_tiles = [(state[i][j], i) for i in range(N) if state[i][j] != 0 and (state[i][j] - 1) % N == j]
        col_tiles.sort(key=lambda x: divmod(x[0] - 1, N)[0])
        for k in range(1, len(col_tiles)):
            if col_tiles[k][1] < col_tiles[k - 1][1]:
                score += (N - col_tiles[k][1])

    return score

def score_state(state):
    N = len(state)
    score = 0
    center_i, center_j = (N - 1) / 2.0, (N - 1) / 2.0

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                manhattan_distance = abs(i - target_i) + abs(j - target_j)
                score += manhattan_distance

                # Calculate distance from the center
                center_distance = abs(i - center_i) + abs(j - center_j)

                # Apply exponential decay factor based on center distance
                weight_factor = 0.5 ** (center_distance / N)

                # Check row sequence penalty with exponential decay weighting
                if j > 0 and state[i][j-1] != 0:
                    prev_value = state[i][j-1]
                    if (prev_value - 1) // N == i and value != prev_value + 1:
                        score += weight_factor * abs(j - target_j)

                # Check column sequence penalty with exponential decay weighting
                if i > 0 and state[i-1][j] != 0:
                    above_value = state[i-1][j]
                    if (above_value - 1) % N == j and value != above_value + N:
                        score += weight_factor * abs(i - target_i)

    return score

def score_state(state):
    N = len(state)
    score = 0

    row_positions = [set() for _ in range(N)]
    col_positions = [set() for _ in range(N)]

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                distance = abs(i - target_i) + abs(j - target_j)
                score += distance
                row_positions[target_i].add((value, j))
                col_positions[target_j].add((value, i))

    def count_misplaced_neighbors(positions):
        sorted_positions = sorted(positions, key=lambda x: x[0])
        misplaced = 0
        for k in range(1, len(sorted_positions)):
            if sorted_positions[k][1] < sorted_positions[k - 1][1]:
                misplaced += 1
        return misplaced

    for positions in row_positions:
        score += count_misplaced_neighbors(positions)

    for positions in col_positions:
        score += count_misplaced_neighbors(positions)

    total_difference = sum(abs(i - j) for i in range(N * N) 
                           for j, k in enumerate(state[i // N][i % N]) if state[i // N][i % N] != 0)

    score += total_difference / (N * N)

    return score

def score_state(state):
    N = len(state)
    score = 0
    total_distance = 0

    def manhattan_distance(i, j, target_i, target_j):
        return abs(i - target_i) + abs(j - target_j)

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                distance = manhattan_distance(i, j, target_i, target_j)
                total_distance += distance
                score += distance

    def linear_conflicts(row_or_col):
        conflicts = 0
        for i in range(N - 1):
            for j in range(i + 1, N):
                a, b = row_or_col[i], row_or_col[j]
                if a != 0 and b != 0:
                    target_a_i, _ = divmod(a - 1, N)
                    target_b_i, _ = divmod(b - 1, N)
                    if (target_a_i == target_b_i and i > j) or (a < b and i < j):
                        conflicts += 2
        return conflicts

    row_conflicts = sum(linear_conflicts([state[i][j] for j in range(N)]) for i in range(N))
    col_conflicts = sum(linear_conflicts([state[i][j] for i in range(N)]) for j in range(N))

    score += (row_conflicts + col_conflicts) * 2
    score += total_distance / N

    return score

def score_state(state):
    N = len(state)
    manhattan_distance_sum = 0
    correct_row_col_count = 0

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value == 0:
                continue
            target_i, target_j = divmod(value - 1, N)
            manhattan_distance_sum += abs(i - target_i) + abs(j - target_j)
            if (i == target_i or j == target_j):
                correct_row_col_count += 1

    return manhattan_distance_sum

def score_state(state):
    N = len(state)
    score = 0
    center_i, center_j = (N - 1) / 2.0, (N - 1) / 2.0

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                manhattan_distance = abs(i - target_i) + abs(j - target_j)
                score += manhattan_distance

                # Calculate distance from the center
                center_distance = max(abs(i - center_i), abs(j - center_j))

                # Apply linear decay factor based on center distance
                weight_factor = 1 - (center_distance / (N * 2.0))

                # Row sequence penalty with linear weighting
                if j > 0 and state[i][j-1] != 0:
                    prev_value = state[i][j-1]
                    if (prev_value - 1) // N == i and value != prev_value + 1:
                        score += weight_factor * abs(j - target_j)

                # Column sequence penalty with linear weighting
                if i > 0 and state[i-1][j] != 0:
                    above_value = state[i-1][j]
                    if (above_value - 1) % N == j and value != above_value + N:
                        score += weight_factor * abs(i - target_i)

    return score

