    N = len(state)
    score = 0
    total_distance = 0
    row_positions = [set() for _ in range(N)]
    col_positions = [set() for _ in range(N)]

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                distance = abs(i - target_i) + abs(j - target_j)
                total_distance += distance
                score += distance
                row_positions[target_i].add((value, j))
                col_positions[target_j].add((value, i))

    def count_non_linear_conflicts(positions):
        sorted_positions = sorted(positions, key=lambda x: x[0])
        conflicts = 0
        for k in range(1, len(sorted_positions)):
            if sorted_positions[k][1] < sorted_positions[k - 1][1]:
                conflicts += 1 + abs(sorted_positions[k][1] - sorted_positions[k - 1][1])
        return conflicts

    def count_blocked_tiles(state, i, j):
        blocked = 0
        target_i, target_j = divmod(value - 1, N)
        for x in range(min(i, target_i) + 1, max(i, target_i)):
            if state[x][j] != 0:
                blocked += 1
        for y in range(min(j, target_j) + 1, max(j, target_j)):
            if state[i][y] != 0:
                blocked += 1
        return blocked

    for positions in row_positions:
        score += count_non_linear_conflicts(positions) * 3
        score += sum(count_blocked_tiles(state, i, j) for value, j in positions)

    for positions in col_positions:
        score += count_non_linear_conflicts(positions) * 2
        score += sum(count_blocked_tiles(state, i, j) for value, i in positions)

    return score

