def score_state(state):
    N = len(state)
    target_positions = {(i + 1): (i // N, i % N) for i in range(1, N * N)}
    manhattan_distance_sum = 0
    linear_conflicts = 0

    # Calculate Manhattan distance sum
    for i in range(N):
        for j in range(N):
            tile = state[i][j]
            if tile != 0:
                target_i, target_j = target_positions[tile]
                manhattan_distance_sum += abs(i - target_i) + abs(j - target_j)

    # Calculate linear conflicts
    for i in range(N):
        row_tiles = [(state[i][j], j) for j in range(N) if state[i][j] != 0]
        sorted_row_tiles = sorted(row_tiles, key=lambda x: target_positions[x[0]][1])
        for k in range(len(sorted_row_tiles)):
            tile, pos = sorted_row_tiles[k]
            target_j = target_positions[tile][1]
            for l in range(k + 1, len(sorted_row_tiles)):
                other_tile, other_pos = sorted_row_tiles[l]
                other_target_j = target_positions[other_tile][1]
                if pos > other_pos and target_j < other_target_j:
                    linear_conflicts += 2

    for j in range(N):
        col_tiles = [(state[i][j], i) for i in range(N) if state[i][j] != 0]
        sorted_col_tiles = sorted(col_tiles, key=lambda x: target_positions[x[0]][0])
        for k in range(len(sorted_col_tiles)):
            tile, pos = sorted_col_tiles[k]
            target_i = target_positions[tile][0]
            for l in range(k + 1, len(sorted_col_tiles)):
                other_tile, other_pos = sorted_col_tiles[l]
                other_target_i = target_positions[other_tile][0]
                if pos > other_pos and target_i < other_target_i:
                    linear_conflicts += 2

    return manhattan_distance_sum

