                        score += 2.0

    # Penalty for the distance of the empty slot to the nearest misplaced tile
    empty_i, empty_j = next((i, j) for i in range(N) for j in range(N) if state[i][j] == 0)
    min_misplaced_distance = N * N
    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                if (i != target_i) or (j != target_j):
                    misplaced_distance = abs(i - empty_i) + abs(j - empty_j)
                    min_misplaced_distance = min(min_misplaced_distance, misplaced_distance)

    score += 0.5 * min_misplaced_distance

    return score

def score_state(state):
    N = len(state)
    score = 0
    row_positions = [set() for _ in range(N)]
    col_positions = [set() for _ in range(N)]

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                score += abs(i - target_i) + abs(j - target_j)
                row_positions[target_i].add((value, j))
                col_positions[target_j].add((value, i))
                if i != target_i or j != target_j:
                    score += 1  # Additional penalty for being in the wrong row or column

    def count_misplaced_neighbors(positions):
        sorted_positions = sorted(positions, key=lambda x: x[0])
        misplaced = 0
        for k in range(1, len(sorted_positions)):
            if sorted_positions[k][1] < sorted_positions[k - 1][1]:
                misplaced += 1
        return misplaced

    for positions in row_positions:
        score += count_misplaced_neighbors(positions)

    for positions in col_positions:
        score += count_misplaced_neighbors(positions)

    return score

def score_state(state):
    N = len(state)
    score = 0
    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                manhattan_distance = abs(i - target_i) + abs(j - target_j)
                score += manhattan_distance
                blocking_tiles = 0
                if i < target_i:
                    for x in range(i + 1, target_i):
                        if state[x][j] != 0 and (state[x][j] - 1) // N == target_i:
                            blocking_tiles += 1
                elif i > target_i:
                    for x in range(target_i + 1, i):
                        if state[x][j] != 0 and (state[x][j] - 1) // N == target_i:
                            blocking_tiles += 1
                if j < target_j:
                    for y in range(j + 1, target_j):
                        if state[i][y] != 0 and (state[i][y] - 1) % N == target_j:
                            blocking_tiles += 1
                elif j > target_j:
                    for y in range(target_j + 1, j):
                        if state[i][y] != 0 and (state[i][y] - 1) % N == target_j:
                            blocking_tiles += 1
                score += blocking_tiles * 2
                if i == target_i or j == target_j:
                    score -= 0.5
    return score

def score_state(state):
    N = len(state)
    score = 0
    total_distance = 0

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                distance = abs(i - target_i) + abs(j - target_j)
                total_distance += distance
                score += distance * (distance + 1) / 2

    for i in range(N):
        row_sorted = sorted([(state[i][j], j) for j in range(N) if state[i][j] != 0])
        col_sorted = sorted([(state[j][i], j) for j in range(N) if state[j][i] != 0])

        for k in range(1, len(row_sorted)):
            if row_sorted[k][1] < row_sorted[k - 1][1]:
                score += 3

        for k in range(1, len(col_sorted)):
            if col_sorted[k][1] < col_sorted[k - 1][1]:
                score += 2

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                obstructed_paths = 0
                for x in range(min(i, target_i) + 1, max(i, target_i)):
                    if state[x][j] != 0:
                        obstructed_paths += (abs(x - target_i) + abs(j - target_j)) * 0.5
                for y in range(min(j, target_j) + 1, max(j, target_j)):
                    if state[i][y] != 0:
                        obstructed_paths += (abs(i - target_i) + abs(y - target_j)) * 0.5
                score += obstructed_paths

    score += total_distance / (N * 2)

    return score

def score_state(state):
    N = len(state)
    score = 0
    misplaced_tiles = set()

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                goal_i, goal_j = divmod(value - 1, N)
                manhattan_distance = abs(i - goal_i) + abs(j - goal_j)
                score += manhattan_distance
                if i != goal_i or j != goal_j:
                    misplaced_tiles.add((i, j))

    for row in range(N):
        max_value_in_row = 0
        for col in range(N):
            value = state[row][col]
            if value != 0 and (value - 1) // N == row:
                if value > max_value_in_row:
                    max_value_in_row = value
                else:
                    score += 2

    for col in range(N):
        max_value_in_col = 0
        for row in range(N):
            value = state[row][col]
            if value != 0 and (value - 1) % N == col:
                if value > max_value_in_col:
                    max_value_in_col = value
                else:
                    score += 2

    empty_i, empty_j = next((i, j) for i in range(N) for j in range(N) if state[i][j] == 0)

    for (i, j) in misplaced_tiles:
        value = state[i][j]
        goal_i, goal_j = divmod(value - 1, N)
        min_penalty = float('inf')

        for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            ni, nj = i + di, j + dj
            if 0 <= ni < N and 0 <= nj < N and state[ni][nj] != 0:
                n_value = state[ni][nj]
                n_goal_i, n_goal_j = divmod(n_value - 1, N)
                penalty = abs(ni - goal_i) + abs(nj - goal_j)
                if penalty == 0:
                    min_penalty = 0
                    break
                else:
                    dynamic_weight = (abs(empty_i - i) + abs(empty_j - j)) / N + 1
                    min_penalty = min(min_penalty, penalty * dynamic_weight)

        score += min_penalty

    return score

def score_state(state):
    N = len(state)
    manhattan_distance = 0
    row_penalty = 0
    col_penalty = 0

    for i in range(N):
        row_seen = set()
        col_seen = set()
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                manhattan_distance += abs(i - target_i) + abs(j - target_j)

                if (value - 1) // N != i:
                    row_penalty += 1
                if (value - 1) % N != j:
                    col_penalty += 1

    return manhattan_distance

def score_state(state):
    N = len(state)
    target_positions = {(i + 1): (i // N, i % N) for i in range(1, N * N)}
    linear_conflicts = 0

    # Check rows for conflicts
    for i in range(N):
        row_tiles = [state[i][j] for j in range(N) if state[i][j] != 0]
        sorted_row_tiles = sorted(row_tiles, key=lambda x: target_positions[x])
        for j in range(len(sorted_row_tiles)):
            for k in range(j + 1, len(sorted_row_tiles)):
                if target_positions[sorted_row_tiles[j]][0] == target_positions[sorted_row_tiles[k]][0]:
                    linear_conflicts += 1

    # Check columns for conflicts
    for j in range(N):
        col_tiles = [state[i][j] for i in range(N) if state[i][j] != 0]
        sorted_col_tiles = sorted(col_tiles, key=lambda x: target_positions[x])
        for i in range(len(sorted_col_tiles)):
            for k in range(i + 1, len(sorted_col_tiles)):
                if target_positions[sorted_col_tiles[i]][1] == target_positions[sorted_col_tiles[k]][1]:
                    linear_conflicts += 1

    return linear_conflicts

def score_state(state):
    N = len(state)
    score = 0

    # Calculate Manhattan distance
    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                goal_i, goal_j = divmod(value - 1, N)
                manhattan_distance = abs(i - goal_i) + abs(j - goal_j)
                score += manhattan_distance

    # Calculate inversions in rows and columns
    for i in range(N):
        row_tiles = [state[i][j] for j in range(N) if state[i][j] != 0]
        for k in range(len(row_tiles)):
            for l in range(k + 1, len(row_tiles)):
                if row_tiles[k] > row_tiles[l]:
                    score += 2

    for j in range(N):
        col_tiles = [state[i][j] for i in range(N) if state[i][j] != 0]
        for k in range(len(col_tiles)):
            for l in range(k + 1, len(col_tiles)):
                if col_tiles[k] > col_tiles[l]:
                    score += 2

    # Discount factor based on proximity to center
    center_i, center_j = N // 2, N // 2
    discount_factor = 0.9
    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                goal_i, goal_j = divmod(value - 1, N)
                distance_to_center = abs(i - center_i) + abs(j - center_j)
                score *= discount_factor ** distance_to_center

    return score

def score_state(state):
    N = len(state)
    score = 0

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                manhattan_distance = abs(i - target_i) + abs(j - target_j)
                score += manhattan_distance

                # Calculate distance from the edges
                edge_distance = min(i, j, N - i - 1, N - j - 1)

                # Apply sigmoid decay factor based on edge distance
                weight_factor = 1 / (1 + 2 ** (-edge_distance))

                # Row sequence penalty with sigmoid weighting
                if j > 0 and state[i][j-1] != 0:
                    prev_value = state[i][j-1]
                    if (prev_value - 1) // N == i and value != prev_value + 1:
                        score += weight_factor * abs(j - target_j)

                # Column sequence penalty with sigmoid weighting
                if i > 0 and state[i-1][j] != 0:
                    above_value = state[i-1][j]
                    if (above_value - 1) % N == j and value != above_value + N:
                        score += weight_factor * abs(i - target_i)

    return score

def score_state(state):
    N = len(state)
