    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                manhattan_distance = abs(i - target_i) + abs(j - target_j)
                score += manhattan_distance * value
    return score

def score_state(state):
    N = len(state)
    score = 0

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                manhattan_distance = abs(i - target_i) + abs(j - target_j)
                score += manhattan_distance

                # Calculate distance from the edge
                edge_distance = min(i, j, N - i - 1, N - j - 1)

                # Apply exponential decay factor based on edge distance
                decay_factor = (0.5 ** (N - edge_distance - 1))

                # Check row sequence penalty with exponential decay
                if j > 0 and state[i][j-1] != 0:
                    prev_value = state[i][j-1]
                    if (prev_value - 1) // N == i and value != prev_value + 1:
                        score += manhattan_distance * abs(j - target_j) * decay_factor

                # Check column sequence penalty with exponential decay
                if i > 0 and state[i-1][j] != 0:
                    above_value = state[i-1][j]
                    if (above_value - 1) % N == j and value != above_value + N:
                        score += manhattan_distance * abs(i - target_i) * decay_factor

    return score
